/** Separate allocation book. No method creates/edits cash transactions, plans or recurring rules. */
@Service @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
class SavingsService {
 private static final BigDecimal ZERO=new BigDecimal("0.00");

 private final JdbcTemplate jdbc;private final FinanceService finance;private final ForecastService forecasts;
 private final AccountRepository accounts;private final TransactionRepository transactions;private final Clock clock;
 record Row(UUID id,String name,String description,BigDecimal target,LocalDate date,boolean completed,boolean archived,Instant created,long version,UUID requestId,String fingerprint){}
 SavingsService(JdbcTemplate jdbc,FinanceService finance,ForecastService forecasts,AccountRepository accounts,TransactionRepository transactions,Clock clock){this.jdbc=jdbc;this.finance=finance;this.forecasts=forecasts;this.accounts=accounts;this.transactions=transactions;this.clock=clock;}
 private LocalDate today(){return LocalDate.now(clock);}
 private Row row(ResultSet r,int n)throws SQLException{return new Row(r.getObject("id",UUID.class),r.getString("name"),r.getString("description"),r.getBigDecimal("target_amount"),r.getObject("target_date",LocalDate.class),r.getBoolean("completed"),r.getBoolean("archived"),r.getTimestamp("created_at").toInstant(),r.getLong("version"),r.getObject("request_id",UUID.class),r.getString("creation_fingerprint"));}
 private List<Row> rows(){return jdbc.query("SELECT * FROM savings_goals WHERE user_id=? AND account_id=? ORDER BY created_at,id",this::row,CurrentIdentity.userId(),CurrentIdentity.accountId());}
 private Row owned(UUID id){var r=jdbc.query("SELECT * FROM savings_goals WHERE id=? AND user_id=? AND account_id=?",this::row,id,CurrentIdentity.userId(),CurrentIdentity.accountId());if(r.isEmpty())throw error(HttpStatus.NOT_FOUND,"Savings goal not found");return r.getFirst();}
 private void lock(){accounts.lockOwned(CurrentIdentity.accountId(),CurrentIdentity.userId()).orElseThrow(()->error(HttpStatus.NOT_FOUND,"Account not found"));}
 private void version(Row r,long v){if(r.version()!=v)throw error(HttpStatus.CONFLICT,"Goal changed. Refresh before trying again");}
 private void open(Row r){if(r.archived()||r.completed())throw error(HttpStatus.CONFLICT,"Restore or reopen the goal before changing allocations or its schedule");}
 private void bump(UUID id){jdbc.update("UPDATE savings_goals SET version=version+1 WHERE id=? AND user_id=?",id,CurrentIdentity.userId());}
 List<Goal> list(){return rows().stream().map(r->view(r,entries(r.id(),false))).toList();}
 Dashboard dashboard(){var goals=list();BigDecimal targets=goals.stream().map(g->new BigDecimal(g.targetAmount())).reduce(ZERO,BigDecimal::add),saved=goals.stream().map(g->new BigDecimal(g.saved())).reduce(ZERO,BigDecimal::add),internal=goals.stream().map(g->new BigDecimal(g.inAccount())).reduce(ZERO,BigDecimal::add),external=goals.stream().map(g->new BigDecimal(g.external())).reduce(ZERO,BigDecimal::add),actual=finance.account().balance();int active=(int)goals.stream().filter(g->!g.archived()&&!g.completed()).count(),complete=(int)goals.stream().filter(Goal::completed).count(),archived=(int)goals.stream().filter(Goal::archived).count(),approaching=(int)goals.stream().filter(g->!g.archived()&&!g.completed()&&g.targetDate()!=null&&!g.targetDate().isBefore(today())&&!g.targetDate().isAfter(today().plusDays(30))).count();return new Dashboard(new Summary(goals.size(),active,archived,complete,approaching,money(targets),money(saved),percent(saved,targets),money(actual),money(internal),money(external),money(actual.subtract(internal)),today()),goals);}
 Detail detail(UUID id){var r=owned(id);var entries=entries(id,true);var goal=view(r,entries);var schedule=schedule(id,r.version());return new Detail(goal,entries,schedule,project(goal,entries,schedule));}
 @Transactional(isolation=Isolation.READ_COMMITTED) Detail create(GoalInput input){lock();String fp=hash(input.name().strip(),text(input.description()),input.targetAmount().stripTrailingZeros(),input.targetDate());var previous=jdbc.query("SELECT * FROM savings_goals WHERE user_id=? AND request_id=?",this::row,CurrentIdentity.userId(),input.requestId());if(!previous.isEmpty()){if(!previous.getFirst().fingerprint().equals(fp))throw error(HttpStatus.CONFLICT,"Request ID already belongs to another goal");return detail(previous.getFirst().id());}validateGoal(input);if(rows().size()>=100)throw error(HttpStatus.BAD_REQUEST,"At most 100 retained goals are supported");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO savings_goals(id,user_id,account_id,name,description,target_amount,target_date,created_at,request_id,creation_fingerprint) VALUES (?,?,?,?,?,?,?,?,?,?)",id,CurrentIdentity.userId(),CurrentIdentity.accountId(),input.name().strip(),text(input.description()),input.targetAmount(),input.targetDate(),Timestamp.from(clock.instant()),input.requestId(),fp);return detail(id);}
 @Transactional(isolation=Isolation.READ_COMMITTED) Detail update(UUID id,GoalUpdate input){lock();var r=owned(id);version(r,input.version());if(r.archived())throw error(HttpStatus.CONFLICT,"Restore an archived goal before editing");validateGoal(input.goal());if(!input.goal().requestId().equals(r.requestId()))throw error(HttpStatus.BAD_REQUEST,"Creation request ID cannot change");if(r.completed()&&input.goal().targetAmount().compareTo(new BigDecimal(view(r,entries(id,false)).saved()))>0)throw error(HttpStatus.CONFLICT,"Reopen the completed goal before increasing its target above saved allocations");jdbc.update("UPDATE savings_goals SET name=?,description=?,target_amount=?,target_date=?,version=version+1 WHERE id=? AND user_id=?",input.goal().name().strip(),text(input.goal().description()),input.goal().targetAmount(),input.goal().targetDate(),id,CurrentIdentity.userId());return detail(id);}
 @Transactional(isolation=Isolation.READ_COMMITTED) Detail state(UUID id,StateInput input){lock();var r=owned(id);version(r,input.version());switch(input.action()){case ARCHIVE->jdbc.update("UPDATE savings_goals SET archived=TRUE WHERE id=? AND user_id=?",id,CurrentIdentity.userId());case RESTORE->jdbc.update("UPDATE savings_goals SET archived=FALSE WHERE id=? AND user_id=?",id,CurrentIdentity.userId());case COMPLETE->{open(r);if(new BigDecimal(view(r,entries(id,false)).saved()).compareTo(r.target())<0)throw error(HttpStatus.BAD_REQUEST,"Saved allocations must meet the target before completion");jdbc.update("UPDATE savings_goals SET completed=TRUE WHERE id=? AND user_id=?",id,CurrentIdentity.userId());}case REOPEN->{if(r.archived())throw error(HttpStatus.CONFLICT,"Restore the goal first");jdbc.update("UPDATE savings_goals SET completed=FALSE WHERE id=? AND user_id=?",id,CurrentIdentity.userId());}}bump(id);return detail(id);}
 private void validateGoal(GoalInput input){if(input.name().isBlank()||input.name().strip().length()>100)throw error(HttpStatus.BAD_REQUEST,"Choose a goal name up to 100 characters");amount(input.targetAmount());if(input.targetDate()!=null&&(input.targetDate().isBefore(LocalDate.of(1900,1,1))||input.targetDate().isAfter(today().plusDays(ForecastService.MAX_DAYS))))throw error(HttpStatus.BAD_REQUEST,"Target date must be from 1900 through the 3660-day horizon");}
 private List<Entry> entries(UUID id,boolean inspectLinks){Map<UUID,ApiModels.TransactionView> cash=new HashMap<>();if(inspectLinks)for(var t:finance.list())cash.put(t.id(),t);return jdbc.query("SELECT e.*,c.reason AS correction_reason FROM savings_entries e LEFT JOIN savings_corrections c ON c.entry_id=e.id AND c.user_id=e.user_id WHERE e.goal_id=? AND e.user_id=? ORDER BY e.entry_date,e.created_at,e.id",(r,n)->{UUID transaction=r.getObject("transaction_id",UUID.class);var t=cash.get(transaction);BigDecimal value=r.getBigDecimal("amount");LocalDate date=r.getObject("entry_date",LocalDate.class);return new Entry(r.getObject("id",UUID.class),money(value),EntryType.valueOf(r.getString("entry_type")),Bucket.valueOf(r.getString("bucket")),date,r.getString("note"),transaction,r.getBoolean("active"),inspectLinks&&transaction!=null&&t==null,inspectLinks&&transaction!=null&&t!=null&&(t.amount().compareTo(value)!=0||!t.date().equals(date)||t.type()!=direction(EntryType.valueOf(r.getString("entry_type")),Bucket.valueOf(r.getString("bucket")))),r.getObject("replaces_id",UUID.class),r.getString("correction_reason"),r.getTimestamp("created_at").toInstant());},id,CurrentIdentity.userId());}
 private Goal view(Row r,List<Entry> history){BigDecimal internal=net(history,Bucket.IN_ACCOUNT),external=net(history,Bucket.EXTERNAL),saved=internal.add(external);return new Goal(r.id(),r.name(),r.description(),money(r.target()),r.date(),r.created(),r.archived()?"ARCHIVED":r.completed()?"COMPLETED":"ACTIVE",r.archived(),r.completed(),money(saved),money(internal),money(external),money(r.target().subtract(saved).max(ZERO)),percent(saved,r.target()),r.version(),r.requestId());}
 private BigDecimal net(List<Entry> rows,Bucket bucket){return rows.stream().filter(Entry::active).filter(e->bucket==null||e.bucket()==bucket).map(e->new BigDecimal(e.amount()).multiply(e.type()==EntryType.CONTRIBUTION?BigDecimal.ONE:BigDecimal.ONE.negate())).reduce(ZERO,BigDecimal::add);}
 @Transactional(isolation=Isolation.READ_COMMITTED) Detail record(UUID goalId,EntryRequest request){lock();var r=owned(goalId);String fp=entryHash(goalId,request.entry(),null);var existing=jdbc.queryForList("SELECT fingerprint,goal_id FROM savings_entries WHERE user_id=? AND request_id=?",CurrentIdentity.userId(),request.requestId());if(!existing.isEmpty()){if(!fp.equals(existing.getFirst().get("fingerprint")))throw error(HttpStatus.CONFLICT,"Request ID already belongs to another allocation");return detail(goalId);}version(r,request.version());open(r);insertEntry(goalId,request.entry(),request.requestId(),fp,null);validateHistory(goalId);bump(goalId);return detail(goalId);}
 @Transactional(isolation=Isolation.READ_COMMITTED) Detail correct(UUID goalId,UUID entryId,Correction request){lock();var r=owned(goalId);String fp=hash(goalId,entryId,request.reason().strip(),request.replacement()==null?"VOID":entryHash(goalId,request.replacement(),entryId));var previous=jdbc.queryForList("SELECT fingerprint FROM savings_corrections WHERE user_id=? AND request_id=?",CurrentIdentity.userId(),request.requestId());if(!previous.isEmpty()){if(!fp.equals(previous.getFirst().get("fingerprint")))throw error(HttpStatus.CONFLICT,"Correction request ID already used");return detail(goalId);}version(r,request.version());open(r);var original=entries(goalId,false).stream().filter(e->e.id().equals(entryId)).findFirst().orElseThrow(()->error(HttpStatus.NOT_FOUND,"Allocation entry not found"));if(!original.active())throw error(HttpStatus.CONFLICT,"Entry is already corrected; correct its active replacement instead");jdbc.update("UPDATE savings_entries SET active=FALSE,active_link_id=NULL WHERE id=? AND user_id=?",entryId,CurrentIdentity.userId());UUID replacement=null;if(request.replacement()!=null)replacement=insertEntry(goalId,request.replacement(),request.requestId(),entryHash(goalId,request.replacement(),entryId),entryId);validateHistory(goalId);jdbc.update("INSERT INTO savings_corrections(id,user_id,goal_id,entry_id,replacement_id,reason,request_id,fingerprint,created_at) VALUES (?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),CurrentIdentity.userId(),goalId,entryId,replacement,request.reason().strip(),request.requestId(),fp,Timestamp.from(clock.instant()));bump(goalId);return detail(goalId);}
 private UUID insertEntry(UUID goalId,EntryInput input,UUID requestId,String fp,UUID replaces){amount(input.amount());if(input.date().isAfter(today())||input.date().isBefore(LocalDate.of(1900,1,1)))throw error(HttpStatus.BAD_REQUEST,"Actual allocation dates must be from 1900 through today; use a schedule for future intentions");if(entries(goalId,false).size()>=10000)throw error(HttpStatus.BAD_REQUEST,"Allocation history limit reached");if(input.transactionId()!=null){var t=transactions.lockOwned(input.transactionId(),CurrentIdentity.userId(),CurrentIdentity.accountId()).orElseThrow(()->error(HttpStatus.NOT_FOUND,"Linked transaction not found"));if(t.amount.compareTo(input.amount())!=0||!t.transactionDate.equals(input.date())||t.type!=direction(input.type(),input.bucket()))throw error(HttpStatus.BAD_REQUEST,"Link a whole payment with matching amount/date and direction: in-account deposits/withdrawals use income/expense; external deposits/withdrawals use expense/income");if(jdbc.queryForObject("SELECT count(*) FROM savings_entries WHERE active_link_id=?",Integer.class,t.id)>0)throw error(HttpStatus.CONFLICT,"This transaction is already linked to an active allocation");}UUID id=UUID.randomUUID();jdbc.update("INSERT INTO savings_entries(id,user_id,goal_id,amount,entry_type,bucket,entry_date,note,transaction_id,active_link_id,replaces_id,request_id,fingerprint,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,CurrentIdentity.userId(),goalId,input.amount(),input.type().name(),input.bucket().name(),input.date(),text(input.note()),input.transactionId(),input.transactionId(),replaces,requestId,fp,Timestamp.from(clock.instant()));return id;}
 private TransactionType direction(EntryType type,Bucket bucket){return (type==EntryType.CONTRIBUTION)==(bucket==Bucket.IN_ACCOUNT)?TransactionType.INCOME:TransactionType.EXPENSE;}
 private void validateHistory(UUID goalId){var history=entries(goalId,false);for(Bucket bucket:Bucket.values()){TreeMap<LocalDate,BigDecimal> daily=new TreeMap<>();for(var e:history)if(e.active()&&e.bucket()==bucket)daily.merge(e.date(),new BigDecimal(e.amount()).multiply(e.type()==EntryType.CONTRIBUTION?BigDecimal.ONE:BigDecimal.ONE.negate()),BigDecimal::add);BigDecimal balance=ZERO;for(var v:daily.values()){balance=balance.add(v);if(balance.signum()<0)throw error(HttpStatus.BAD_REQUEST,"This would overdraw the goal's "+bucket+" allocations on a recorded date. Correct dependent withdrawals first");}}}
 private ScheduleInput schedule(UUID goalId,long version){var values=jdbc.query("SELECT * FROM savings_schedules WHERE goal_id=? AND user_id=?",(r,n)->new ScheduleInput(r.getBigDecimal("amount"),Bucket.valueOf(r.getString("bucket")),r.getString("frequency")==null?null:RecurrenceFrequency.valueOf(r.getString("frequency")),(Integer)r.getObject("payment_day"),(Integer)r.getObject("second_payment_day"),r.getObject("start_date",LocalDate.class),r.getObject("end_date",LocalDate.class),r.getBoolean("enabled"),LinkType.valueOf(r.getString("link_type")),r.getObject("link_id",UUID.class),version),goalId,CurrentIdentity.userId());return values.isEmpty()?null:values.getFirst();}
 @Transactional(isolation=Isolation.READ_COMMITTED) Detail saveSchedule(UUID goalId,ScheduleInput input){lock();var r=owned(goalId);version(r,input.version());open(r);amount(input.amount());if(input.startDate().isBefore(LocalDate.of(1900,1,1))||input.startDate().isAfter(today().plusDays(ForecastService.MAX_DAYS))||input.endDate()!=null&&(input.endDate().isBefore(input.startDate())||input.endDate().isAfter(today().plusDays(ForecastService.MAX_DAYS))))throw error(HttpStatus.BAD_REQUEST,"Choose ordered schedule dates from 1900 through the 3660-day horizon");if(input.linkType()==LinkType.NONE){if(input.linkId()!=null||input.frequency()==null)throw error(HttpStatus.BAD_REQUEST,"Choose a frequency without a cash-flow link");if(Set.of(RecurrenceFrequency.MONTHLY,RecurrenceFrequency.TWICE_MONTHLY).contains(input.frequency())&&(input.paymentDay()==null||input.paymentDay()<1||input.paymentDay()>31))throw error(HttpStatus.BAD_REQUEST,"Choose payment day 1–31");if(input.frequency()==RecurrenceFrequency.TWICE_MONTHLY&&(input.secondPaymentDay()==null||input.secondPaymentDay()<=input.paymentDay()||input.secondPaymentDay()>31))throw error(HttpStatus.BAD_REQUEST,"Choose a larger second payment day up to 31");}else{if(input.linkId()==null)throw error(HttpStatus.BAD_REQUEST,"Choose an owned existing planned or recurring cash flow");if(jdbc.queryForObject("SELECT count(*) FROM savings_schedules WHERE user_id=? AND link_type=? AND link_id=? AND goal_id<>?",Integer.class,CurrentIdentity.userId(),input.linkType().name(),input.linkId(),goalId)>0)throw error(HttpStatus.CONFLICT,"This whole cash flow is already associated with another savings goal");String table=input.linkType()==LinkType.PLANNED?"planned_transactions":"recurring_rules";var cash=jdbc.queryForList("SELECT amount,type FROM "+table+" WHERE id=? AND user_id=? AND account_id=?",input.linkId(),CurrentIdentity.userId(),CurrentIdentity.accountId());if(cash.isEmpty())throw error(HttpStatus.NOT_FOUND,"Linked cash flow not found");if(((BigDecimal)cash.getFirst().get("amount")).compareTo(input.amount())!=0||!cash.getFirst().get("type").equals(input.bucket()==Bucket.EXTERNAL?"EXPENSE":"INCOME"))throw error(HttpStatus.BAD_REQUEST,"The linked flow must match the allocation amount and bucket direction");}jdbc.update("DELETE FROM savings_schedules WHERE goal_id=? AND user_id=?",goalId,CurrentIdentity.userId());jdbc.update("INSERT INTO savings_schedules(goal_id,user_id,amount,bucket,frequency,payment_day,second_payment_day,start_date,end_date,enabled,link_type,link_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",goalId,CurrentIdentity.userId(),input.amount(),input.bucket().name(),input.frequency()==null?null:input.frequency().name(),input.paymentDay(),input.secondPaymentDay(),input.startDate(),input.endDate(),input.enabled(),input.linkType().name(),input.linkId());bump(goalId);return detail(goalId);}
 private RecurringRule adapter(ScheduleInput s){var r=new RecurringRule();r.amount=s.amount();r.frequency=s.frequency();r.startDate=s.startDate();r.endDate=s.endDate();r.paymentDay=s.paymentDay();r.secondPaymentDay=s.secondPaymentDay();return r;}
 private Projection project(Goal goal,List<Entry> history,ScheduleInput schedule){
  LocalDate now=today(),horizon=now.plusDays(ForecastService.MAX_DAYS);List<String> notes=new ArrayList<>();List<Point> points=new ArrayList<>();TreeMap<LocalDate,BigDecimal> daily=new TreeMap<>();TreeMap<YearMonth,BigDecimal[]> monthly=new TreeMap<>();
  for(var e:history)if(e.active()){BigDecimal v=new BigDecimal(e.amount());daily.merge(e.date(),e.type()==EntryType.CONTRIBUTION?v:v.negate(),BigDecimal::add);var m=monthly.computeIfAbsent(YearMonth.from(e.date()),x->new BigDecimal[]{ZERO,ZERO});m[e.type()==EntryType.CONTRIBUTION?0:1]=m[e.type()==EntryType.CONTRIBUTION?0:1].add(v);}
  BigDecimal cumulative=ZERO;for(var e:daily.entrySet()){cumulative=cumulative.add(e.getValue());points.add(new Point(e.getKey(),money(cumulative),null));}points.add(new Point(now,goal.saved(),goal.saved()));
  String method="insufficient_history";TreeMap<LocalDate,BigDecimal> future=new TreeMap<>();BigDecimal saved=new BigDecimal(goal.saved()),target=new BigDecimal(goal.targetAmount()),remaining=new BigDecimal(goal.remaining());
  if(!goal.archived()&&!goal.completed()){
   ScheduleInput effective=schedule;
   if(effective==null){BigDecimal total=ZERO;boolean enough=true;for(int i=3;i>=1;i--){var v=monthly.get(YearMonth.from(now).minusMonths(i));if(v==null||v[0].subtract(v[1]).signum()<=0){enough=false;break;}total=total.add(v[0].subtract(v[1]));}if(enough){BigDecimal rate=total.divide(new BigDecimal("3"),2,RoundingMode.HALF_UP);if(rate.signum()>0){effective=new ScheduleInput(rate,Bucket.IN_ACCOUNT,RecurrenceFrequency.MONTHLY,now.getDayOfMonth(),null,now.plusMonths(1),null,true,LinkType.NONE,null,goal.version());method="historical_monthly_net";notes.add("Historical net allocations over three positive complete months / 3 are repeated monthly on the current day, clamped at month-end. This is an estimate, not a promise.");}}}
   else method=effective.enabled()?"planned_allocations":"paused_schedule";
   if(effective!=null&&effective.enabled()){
    if(effective.linkType()==LinkType.NONE){var r=adapter(effective);for(var date=RecurrenceDates.onOrAfter(r,now.plusDays(1));date!=null&&!date.isAfter(horizon);date=RecurrenceDates.after(r,date))future.put(date,effective.amount());}
    else {var linked=forecasts.forecast(horizon);String expectedSource=effective.linkType()==LinkType.PLANNED?"PLANNED":"RECURRING";String direction=effective.bucket()==Bucket.EXTERNAL?"EXPENSE":"INCOME";int mismatches=0;for(var day:linked.days())for(var event:day.transactions())if(event.source().equals(expectedSource)&&event.sourceId().equals(effective.linkId())&&!event.scheduledDate().isBefore(effective.startDate())&&(effective.endDate()==null||!event.scheduledDate().isAfter(effective.endDate()))&&event.scheduledDate().isAfter(now)){if(new BigDecimal(event.amount()).compareTo(effective.amount())==0&&event.type().name().equals(direction))future.merge(event.scheduledDate(),effective.amount(),BigDecimal::add);else mismatches++;}notes.add("Allocation dates come only from still-pending linked cash-flow events; handled, posted, paused or canceled flows contribute no forecast allocation. Stale amounts/directions are withheld ("+mismatches+"). The bank engine counts the existing cash flow once.");}
   }
  }
  LocalDate complete=saved.compareTo(target)>=0?now:null;BigDecimal projected=saved,expected=goal.targetDate()==null?null:saved;int byTarget=0;for(var event:future.entrySet()){projected=projected.add(event.getValue());if(complete==null&&projected.compareTo(target)>=0)complete=event.getKey();if(goal.targetDate()!=null&&!event.getKey().isAfter(goal.targetDate())){expected=projected;byTarget++;}points.add(new Point(event.getKey(),null,money(projected)));}
  if(goal.targetDate()!=null&&goal.targetDate().isBefore(now)){expected=null;notes.add("Target date has passed. Future intentions cannot establish what was saved historically by that date.");}
  int opportunities=0;if(goal.targetDate()!=null&&goal.targetDate().isAfter(now))for(var m=YearMonth.from(now);!m.isAfter(YearMonth.from(goal.targetDate()));m=m.plusMonths(1)){LocalDate date=m.atEndOfMonth().isAfter(goal.targetDate())?goal.targetDate():m.atEndOfMonth();if(date.isAfter(now))opportunities++;}
  String required=opportunities==0?null:money(remaining.divide(BigDecimal.valueOf(opportunities),2,RoundingMode.CEILING));String per=byTarget==0?null:money(remaining.divide(BigDecimal.valueOf(byTarget),2,RoundingMode.CEILING));
  if(required!=null)notes.add("Required monthly amount divides remaining allocations by "+opportunities+" remaining month-end opportunities (the final one is clamped to the target date), rounded upward to cents; excludes today.");
  if(method.equals("insufficient_history"))notes.add("No active allocation schedule and fewer than three complete positive-net contribution months: no completion date is invented.");if(complete==null)notes.add("No completion estimate within the 3660-day horizon under these assumptions.");
  if(goal.archived()||goal.completed())notes.add("Archived/completed goals do not project new allocations; recorded savings remain reserved until explicitly withdrawn after restore/reopen.");
  LocalDate plotThrough=complete==null?now.plusMonths(12):complete;if(goal.targetDate()!=null&&goal.targetDate().isAfter(plotThrough))plotThrough=goal.targetDate();final LocalDate plotEnd=plotThrough;points=points.stream().filter(p->p.projected()==null||!p.date().isAfter(plotEnd)).toList();notes.add("Chart projections stop at the later of supported completion and target date; without either they show twelve months. Full estimates remain bounded to 3660 days.");
  LocalDate bankDate=now.plusMonths(12);var bank=forecasts.forecast(bankDate);notes.add("Allocation projections assume no unentered withdrawals and never alter the bank forecast. Actual recorded allocations are not cash movements; outside-account savings are excluded from in-account reservations. Missed intended allocations are not auto-recorded or backfilled.");
  return new Projection(now,horizon,method,complete,expected==null?null:money(expected),required,per,byTarget,bank.summary().projectedBalance(),bankDate,List.copyOf(points),monthly.entrySet().stream().map(e->new Month(e.getKey().toString(),money(e.getValue()[0]),money(e.getValue()[1]),money(e.getValue()[0].subtract(e.getValue()[1])))).toList(),List.copyOf(notes));
 }
 private String entryHash(UUID id,EntryInput e,UUID replaces){return hash(id,e.amount().stripTrailingZeros(),e.type(),e.bucket(),e.date(),text(e.note()),e.transactionId(),replaces);}
 private String hash(Object... fields){try{StringBuilder s=new StringBuilder();for(var field:fields){String v=String.valueOf(field);s.append(v.length()).append(':').append(v);}return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.toString().getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("Fingerprint unavailable");}}
 private void amount(BigDecimal amount){if(amount==null||amount.signum()<=0||amount.scale()>2||amount.precision()-amount.scale()>12)throw error(HttpStatus.BAD_REQUEST,"Use positive money with at most twelve integer digits and two decimal places");}
 private String text(String value){return value==null?"":value.strip();}
 private String money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP).toPlainString();}
 private String percent(BigDecimal n,BigDecimal d){return d.signum()==0?"0.00":n.multiply(new BigDecimal("100")).divide(d,2,RoundingMode.HALF_UP).toPlainString();}
 private ResponseStatusException error(HttpStatus status,String detail){return new ResponseStatusException(status,detail);}
}
